const CACHE_TTL = 30 * 60 * 1000; // 30 minutes
const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tbltYZZMUsQg5rxPC';

const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') args = JSON.parse(args);

// Build cache key and Airtable filter
let cacheKey, formula;
if (args.category) {
  cacheKey = 'cat_' + args.category;
  formula = 'AND({Available}=TRUE(),{Category}="' + args.category + '")';
} else if (args.item) {
  cacheKey = 'item_' + args.item.toLowerCase();
  formula = 'AND({Available}=TRUE(),SEARCH(LOWER("' + args.item + '"),LOWER({Item Name})))';
} else if (args.query) {
  cacheKey = 'q_' + args.query.toLowerCase();
  formula = 'AND({Available}=TRUE(),OR(SEARCH(LOWER("' + args.query + '"),LOWER({Item Name})),SEARCH(LOWER("' + args.query + '"),LOWER({Description}))))';
} else {
  cacheKey = 'all';
  formula = '{Available}=TRUE()';
}

// Check cache
const cache = $getWorkflowStaticData('global');
const now = Date.now();
const hit = cache[cacheKey];
let records;

if (hit && (now - hit.ts) < CACHE_TTL) {
  records = hit.data;
} else {
  const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID +
    '?filterByFormula=' + encodeURIComponent(formula) +
    '&fields[]=Item%20Name&fields[]=Category&fields[]=Description&fields[]=Price&fields[]=Available';
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
  records = res.records || [];
  cache[cacheKey] = { data: records, ts: now };
}

if (records.length === 0) {
  return [{ json: { results: [{ toolCallId, result: 'No items found for that query.' }] } }];
}

const lines = records
  .filter(r => r.fields['Available'] !== false)
  .map(r => {
    const f = r.fields;
    const price = f['Price'] != null ? '$' + Number(f['Price']).toFixed(2) : 'price varies';
    const desc = f['Description'] ? ' - ' + f['Description'] : '';
    return f['Item Name'] + ' (' + price + ')' + desc;
  });

return [{ json: { results: [{ toolCallId, result: lines.join('\n') }] } }];
